require __DIR__.'/includes/bootstrap.php';require_login();$id=(int)($_GET['id']??$_POST['id']??0);$stmt=db()->prepare('SELECT r.*,g.title,g.id AS gem_id FROM reviews r JOIN gems g ON g.id=r.gem_id WHERE r.id=?');$stmt->execute([$id]);$review=$stmt->fetch();if(!$review||((int)$review['user_id']!==(int)current_user()['id']&&!is_admin())){http_response_code(403);exit('You cannot edit this review.');}$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$rating=(int)($_POST['rating']??0);$comment=trim((string)($_POST['comment']??''));$vibes=$_POST['vibes']??[];if($rating<1||$rating>5)$errors[]='Select a rating between 1 and 5.';if(mb_strlen($comment)>300)$errors[]='Review must be 300 characters or fewer.';if(!$errors){$status=is_admin()?'approved':((setting('enable_moderation','1')==='1'&&setting('auto_approve_content','0')!=='1')?'pending':'approved');$stmt=db()->prepare('UPDATE reviews SET rating=?,comment=?,vibes=?,status=?,is_edited=1 WHERE id=?');$stmt->execute([$rating,$comment?:null,implode(',',array_slice(is_array($vibes)?$vibes:[],0,4)),$status,$id]);recalculate_gem_rating((int)$review['gem_id']);flash('success',is_admin()?'Review updated.':'Review updated and returned to moderation.');redirect(is_admin()?'admin/moderation.php':'profile.php?tab=reviews');}}
$pageTitle='Edit Your Review';require __DIR__.'/includes/header.php';$selected=tag_list($review['vibes']);
?>
<section class="page-hero"><div class="container"><span class="eyebrow">Update feedback</span><h1>Edit Your Review</h1><p class="muted">Review for <?=e($review['title'])?></p></div></section><section class="section-tight"><div class="container" style="max-width:760px"><?php if($errors):?><div class="toast toast-danger" style="position:static;margin-bottom:16px"><span><?=e(implode(' ',$errors))?></span></div><?php endif;?><div class="content-card"><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><div class="form-group"><label>Rating</label><div class="star-input"><?php for($i=5;$i>=1;$i--):?><input id="edit-star<?=$i?>" name="rating" type="radio" value="<?=$i?>" <?=((int)($_POST['rating']??$review['rating'])===$i)?'checked':''?>><label for="edit-star<?=$i?>">★</label><?php endfor;?></div></div><div class="form-group"><label>Your Review</label><textarea class="form-control" name="comment" maxlength="300" data-char-counter="#edit-review-count"><?=e($_POST['comment']??$review['comment'])?></textarea><div class="char-counter" id="edit-review-count">0/300</div></div><div class="form-group"><label>Vibe & Activity</label><div class="choice-row"><?php foreach(['Romantic','Chill','Food','Date Night'] as $v):?><label class="choice-pill"><input type="checkbox" name="vibes[]" value="<?=e($v)?>" <?=in_array($v,$_POST['vibes']??$selected,true)?'checked':''?>><span><?=e($v)?></span></label><?php endforeach;?></div></div><div class="action-row"><a class="btn btn-ghost" href="<?=url('profile.php?tab=reviews')?>">Cancel</a><button class="btn btn-primary">Save Changes</button></div></form></div></div></section>
